argv:
f=/mnt/bko-target/var/lib/misc/health-check.state; top=/run/bko-holt/btrfs/bc000000-0000-4000-8000-000000000005
subid() { btrfs subvolume show "$1" 2>/dev/null | awk '$1 == "Subvolume" && $2 == "ID:" { print $3; exit }'; }
issub() { [ -n "$(subid "$1")" ]; }
[ -f "$f" ] || { echo "transactional: /var/lib/misc/health-check.state isn't in the restored /var" >&2; exit 1; }
p=$(sed -n 's/^LAST_WORKING_SNAPSHOT=//p' "$f" | tail -n 1); p=${p#\"}; p=${p%\"}; p=${p#\'}; p=${p%\'}
[ -n "$p" ] || { echo "transactional: /var/lib/misc/health-check.state has no LAST_WORKING_SNAPSHOT" >&2; exit 1; }
old=$(sed -n 's/^LAST_WORKING_BTRFS_ID=//p' "$f" | tail -n 1)
new=$(subid "$top/${p#/}")
[ -n "$new" ] || { echo "transactional: /var/lib/misc/health-check.state's LAST_WORKING_SNAPSHOT=$p isn't a subvolume of the restored filesystem: health-checker's rollback would set a default that isn't there" >&2; exit 1; }
if [ "$old" = "$new" ]; then echo "transactional: /var/lib/misc/health-check.state: LAST_WORKING_BTRFS_ID=$new is $p's ID here too; kept"; exit 0; fi
touch -r "$f" /run/bko-holt/hc.ref && sed "s/^LAST_WORKING_BTRFS_ID=.*/LAST_WORKING_BTRFS_ID=$new/" "$f" > /run/bko-holt/hc.new && cat /run/bko-holt/hc.new > "$f" && touch -r /run/bko-holt/hc.ref "$f" || exit 1
echo "transactional: /var/lib/misc/health-check.state: LAST_WORKING_BTRFS_ID $old -> $new ($p's ID here)"

import glob, os, re, sys
slot, t, mps = sys.argv[1], sys.argv[2], sys.argv[3:]
K = "security.selinux"
def get(p):
    try:
        return os.getxattr(p, K, follow_symlinks=False)
    except OSError:
        return None
if get(slot) is None:
    print("transactional: the booted slot's root has no SELinux label: its mount points are left as they are")
    sys.exit(0)
others = re.sub(r"/[0-9]+/snapshot$", "/*/snapshot", slot)
n = 0
for m in mps:
    d = slot + m
    if not os.path.isdir(d) or os.path.islink(d) or get(d) is not None:
        continue
    src = next((o for o in sorted(glob.glob(others + m)) if o != d and os.path.isdir(o) and get(o) is not None), None)
    if src is None and get(t + m) is not None:
        src = t + m
    if src is None:
        print(f"transactional: {m} in the booted slot has no label, and no other slot or mount has one for it")
        continue
    os.setxattr(d, K, get(src), follow_symlinks=False)
    n += 1
    print(f"transactional: {m} in the booted slot (a mount point load made) labelled {get(src).decode(errors='replace').rstrip(chr(0))}, as {src}")
print(f"transactional: {n} of the booted slot's mount points labelled")

import os, sys
name, src, top = sys.argv[1:4]
try:
    v = os.getxattr(src, name, follow_symlinks=False)
except OSError:
    sys.exit(0)
for d, _, files in os.walk(top):
    for p in [d] + [os.path.join(d, f) for f in files]:
        os.setxattr(p, name, v, follow_symlinks=False)
